#pragma once
// R138G: native S2 rendering of actual R36MK GLB geometry and per-triangle image-derived palette.\n// Import actual R36MK 2100 triangle static GLB geometry into
// native Nival S2 IGScene. Does not implement GLB rasterization.
// Runtime opt-in only, isolated binary; no collision/AI/save modifications.
// Input XPZC generated by glb_to_s2.cjs, exact source GLB hash in report.
#include <windows.h>
#include <stdio.h>
#include <stdint.h>
#include <vector>
#include "MemObject.h"
#include "GView.h"

namespace XPZ3DR138E {
struct PacketHeader { char magic[4]; uint32_t version,groups,triangles,reserved[4]; };
struct PartHeader { uint32_t kind,triangles,vertices,reserved; };
static_assert(sizeof(PacketHeader)==32,"R138E header ABI");
static_assert(sizeof(PartHeader)==16,"R138E group ABI");

inline bool Enabled(){
 char v[4]={0};
 return GetEnvironmentVariableA("XPZ3D_R138E_PREVIEW_CHARACTER",v,sizeof(v))==1&&v[0]=='1';
}
inline bool GetDataPath(char (&out)[MAX_PATH]){
 return GetEnvironmentVariableA("XPZ3D_R138E_CHARACTER_MESH_PATH",out,MAX_PATH)>0;
}
inline void Log(const char* line){
 char p[MAX_PATH]={0};DWORD n=GetEnvironmentVariableA("XPZ3D_R138E_CHARACTER_TRACE",p,MAX_PATH);
 if(n>0&&n<MAX_PATH){FILE* f=0;if(fopen_s(&f,p,"ab")==0&&f){fprintf(f,"%s\n",line);fclose(f);}}
}
struct Model {
 NGScene::IGameView* scene;
 CObj<CObjectBase> objects[48];
 bool attempted,loaded;
 unsigned polygons,groups;
 Model():scene(0),attempted(false),loaded(false),polygons(0),groups(0){}
 void Reset(){
  for(int k=0;k<48;++k)objects[k]=0;
  scene=0;attempted=false;loaded=false;polygons=groups=0;
 }
 bool Attach(NGScene::IGameView* s){
  if(!s||!Enabled())return false;
  if(scene!=s){Reset();scene=s;}
  if(attempted)return loaded;
  attempted=true;
  char file[MAX_PATH]={0};
  if(!GetDataPath(file)){Log("R138E_MISSING_CHARACTER_PATH");return false;}
  FILE* f=0;
  if(fopen_s(&f,file,"rb")!=0||!f){Log("R138E_CHARACTER_OPEN_FAILED");return false;}
  bool ok=false;
  do{
   PacketHeader hdr={};
   if(fread(&hdr,1,sizeof(hdr),f)!=sizeof(hdr))break;
   if(memcmp(hdr.magic,"XPZC",4)||(hdr.version!=1&&hdr.version!=2)||hdr.groups<1||hdr.groups>48||hdr.triangles!=2100)break;
   uint32_t nsum=0;
   for(uint32_t gi=0;gi<hdr.groups;++gi){
    PartHeader gp={};
    if(fread(&gp,1,sizeof(gp),f)!=sizeof(gp))break;
    if(gp.vertices!=gp.triangles*3||gp.triangles==0||gp.vertices>15000||gp.kind>5)break;
    std::vector<CVec3> points;
    std::vector<STriangle> triangles;
    points.reserve(gp.vertices);triangles.reserve(gp.triangles);
    for(uint32_t i=0;i<gp.vertices;++i){
     float xyz[3]={0};
     if(fread(xyz,sizeof(float),3,f)!=3){points.clear();break;}
     if(!(xyz[0]>-100.f&&xyz[0]<100.f&&xyz[1]>-100.f&&xyz[1]<100.f&&xyz[2]>-100.f&&xyz[2]<100.f)){points.clear();break;}
     // Native S2 world coordinate. Target sits at tactical-map (25,25,2.5).
     points.push_back(CVec3(25.f+xyz[0],25.f+xyz[1],30.f+xyz[2]));
    }
    if(points.size()!=gp.vertices)break;
    for(uint32_t i=0;i<gp.triangles;++i)
     triangles.push_back(STriangle((int)(i*3),(int)(i*3+1),(int)(i*3+2)));
    const CVec4 colors[]={
     CVec4(.81f,.65f,.55f,1.f), // body
     CVec4(.40f,.31f,.22f,1.f), // hair
     CVec4(.79f,.65f,.58f,1.f), // face
     CVec4(.57f,.53f,.50f,1.f), // armor
     CVec4(.38f,.37f,.36f,1.f), // pants/boots
     CVec4(.70f,.67f,.62f,1.f)  // accessories
    };
    CPtr<CMemObject> mem=new CMemObject;
    mem->Create(points,triangles);
    // Native Nival S2 scene material and GPU draw; not a substitute renderer.
    const CVec4 color=hdr.version==2 ?
      CVec4(float((gp.reserved>>16)&255u)/255.f,
            float((gp.reserved>>8)&255u)/255.f,
            float(gp.reserved&255u)/255.f,1.f) : colors[gp.kind];
    objects[gi]=s->CreateMesh(mem.GetPtr(),color,(CFuncBase<SFBTransform>*)0);
    if(!IsValid(objects[gi]))break;
    nsum+=gp.triangles;groups++;
   }
   if(groups==hdr.groups && nsum==2100){
    polygons=nsum;ok=true;
    char msg[180];sprintf_s(msg,sizeof(msg),"R138G_NATIVE_S2_PALETTE_ATTACHED groups=%u tris=%u scene=%p",groups,polygons,(void*)s);Log(msg);
   }
  }while(false);
  fclose(f);
  if(!ok){for(int k=0;k<48;++k)objects[k]=0;Log("R138E_CHARACTER_ATTACH_FAILED");}
  loaded=ok;
  return loaded;
 }
};
inline Model& Instance(){static Model state;return state;}
inline bool DrawNative(NGScene::IGameView* scene){return Instance().Attach(scene);}
} // namespace
